steps.script:
var st = GameState.state
var p1x = 120.0
var p2x = 120.0
for uid in st.units:
	var u = st.units[uid]
	var own = int(u.get("owner", 0))
	for i in range(u.models.size()):
		if own == 1:
			u.models[i]["position"] = {"x": p1x, "y": 120.0}
			p1x += 70.0
			if p1x > 1650.0:
				p1x = 120.0
		else:
			u.models[i]["position"] = {"x": p2x, "y": 2280.0}
			p2x += 70.0
			if p2x > 1650.0:
				p2x = 120.0
var pairs = [["U_CUSTODIAN_GUARD_B", "U_BOYZ_K", 350.0], ["U_WITCHSEEKERS_C", "U_BOYZ_E", 850.0], ["U_WITCHSEEKERS_D", "U_BOYZ_F", 1350.0]]
for p in pairs:
	var a = st.units[p[0]]
	var b = st.units[p[1]]
	var bx = float(p[2])
	var by = 1000.0
	var ai = -1
	for i in range(a.models.size()):
		if a.models[i].get("alive", true):
			if ai < 0:
				ai = i
			a.models[i]["position"] = {"x": bx + i * 66.0, "y": by}
	var bi = -1
	for j in range(b.models.size()):
		if b.models[j].get("alive", true):
			if bi < 0:
				bi = j
			b.models[j]["position"] = {"x": bx + (j % 4) * 66.0, "y": by + 300.0 + int(j / 4) * 66.0}
	var gap = Measurement.base_extent_px(a.models[ai]) + Measurement.base_extent_px(b.models[bi]) + Measurement.inches_to_px(0.6)
	b.models[bi]["position"] = {"x": bx, "y": by + gap}
return "positioned"

var ph = PhaseManager.get_current_phase_instance()
var e = ph._pile_in_eligible_units_11e(1)
e.sort()
return ",".join(e)

var ph = PhaseManager.get_current_phase_instance()
var k = ph.units_that_piled_in.keys()
k.sort()
return ",".join(k)

var st = GameState.state
var moved = []
for u in ["U_CUSTODIAN_GUARD_B", "U_WITCHSEEKERS_C", "U_WITCHSEEKERS_D"]:
	for m in st.units[u].models:
		if m.get("alive", true) and float(m.position.y) > 1005.0:
			moved.append(u)
			break
moved.sort()
return ",".join(moved)
